        const input = {
            ...(action.agent ? { agent: action.agent } : {}),
            context: this.context,
            label,
            ...(action.model ? { model: action.model } : {}),
            ...(action.permissionMode ? { permissionMode: action.permissionMode } : {}),
            prompt: message.content,
