        const reference = input.runInput.continueFrom
            ? continuationReferencePath(input.runInput.continueFrom)
            : input.conversationReservation?.reference;
        const request = {
            actionId: input.action.id,
            agent: resolvedAgent.agent,
            activityOrigin: input.activityOrigin,
            activityProject: input.primaryProject,
            ...(input.context.file ? { cardPath: input.context.file } : {}),
            command,
            ...(sourceConversation ? { conversation: sourceConversation, reference } : {}),
            ...(!sourceConversation && input.conversationReservation
                ? { conversationId: input.conversationReservation.conversationId, reference }
                : {}),
            ...(contextInput ? { contextInput } : {}),
            actionRunId: input.runId,
            prompt,
            projectFolder: input.projectFolder,
            releasesFolder: input.releasesFolder,
            streaming,
            ...(providerSession ? { providerConversationId: providerSession.conversationId } : {}),
            title: input.action.label,
        };
        const fallback = {
            command: resolvedAgent.command,
            contextInput: sourceConversation ? normalizeConversationContext(sourceConversation) : '',
        };
        const result = await this.runAgentTurn(input, request, fallback);
        const executionResult = withoutConversation(result);

        return {
            ...executionResult,
            agent: resolvedAgent.agent,
            model: resolvedAgent.model,
            permissionMode: resolvedAgent.permissionMode,
            thinkingLevel: resolvedAgent.thinkingLevel,
        };
    }

    async runAgentTurn(input, request, fallback) {
        const result = await this.runAgentProcess(input, request);
        if (!request.providerConversationId || !result.missingSession || result.turnStarted) return result;

        const fallbackRequest = {
            ...withoutProviderConversationId(request),
            command: fallback.command,
            conversation: result.conversation,
            ...(fallback.contextInput ? { contextInput: fallback.contextInput } : {}),
            reference: result.reference,
            reuseLastUserMessage: true,
        };

        return this.runAgentProcess(input, fallbackRequest);
    }

    async runAgentProcess(input, request) {
        const { promise, reject, resolve } = Promise.withResolvers();
        const onComplete = (exitCode, run) => resolve({
            command: request.command,
            changedPaths: run.changedPaths ? [...run.changedPaths] : [],
            conversation: run.conversation,
            conversationId: run.conversation.id,
            exitCode,
            missingSession: run.missingSession,
            prompt: request.prompt,
            reference: run.reference,
            stderr: run.stderr,
            stdout: run.stdout,
            turnStarted: run.turnStarted,

    dismissQuestions(runId, requestId) {
        return agentInteractions.dismissQuestions(this, this.requireStreamingRun(runId), requestId);
    }

    answerApproval(runId, requestId, decision) {
        return agentInteractions.answerApproval(this, this.requireStreamingRun(runId), requestId, decision);
    }

    finish(runId) {
        const run = this.requireStreamingRun(runId);
        run.finishing = true;
        if (!run.turnActive || run.waitingForQuestion) this.beginFinishShutdown(run);
    }

    beginFinishShutdown(run) {
        if (run.finishTimeout !== null && run.finishTimeout !== undefined) return;
        run.finishTimeout = this.setTimeout(this.handleFinishTimeout, AGENT_FINISH_GRACE_MS, run.id);
        run.child.stdin.end();
    }

    clearFinishTimeout(run) {
        if (run.finishTimeout === null || run.finishTimeout === undefined) return;
        this.clearTimeout(run.finishTimeout);
        run.finishTimeout = null;
    }

    async handleFinishTimeout(runId) {
        const run = this.processes.get(runId);
        if (!run) return;
        run.finishTimeout = null;
        console.warn('[agent:finish-timeout]', {
            graceMs: AGENT_FINISH_GRACE_MS,
            pid: run.child.pid,
            runId,
            timestamp: new Date().toISOString(),
        });
        try {
            run.finishForced = await this.ensureTermination(run);
        } catch (error) {
            this.handleError(runId, error);
        }
    }

    stopAll() {
        this.usageRefreshStopped = true;
        this.stopUsagePollTicks();

        if (typeof listener !== 'function') throw new Error('Missing action run listener');
        this.listeners.add(listener);

        return () => this.listeners.delete(listener);
    }

    async start(request, options = {}) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        const origin = activityOrigin(startRequest.context);
        const project = { ...this.project };
        const actionsFolder = this.actionsFolder;
        const rootAction = await this.loadRootAction(startRequest.actionId);
        const diagramPath = this.resolveStartDiagramPath(startRequest, rootAction);
        if (options.interactive === false && hasStreamingAction(rootAction)) {
            throw new Error(`Streaming action requires an interactive manual run: ${rootAction.label}`);
        }
        const conversationReservation = this.consumeConversationReservation(startRequest, rootAction);
        const runId = options.runId ?? createRunId();
        if (typeof runId !== 'string' || runId.length === 0) throw new Error('Invalid reserved action run ID');
        if (this.runs.has(runId) || this.completedRunResults.has(runId)) throw new Error(`Action run already exists: ${runId}`);
        const run = new ActionRun({
            activeCardsFolder: this.activeCardsFolder,
            actionsFolder,
            activityOrigin: origin,
            context: startRequest.context,
            conversationReservation,
            diagramFooter: this.diagramFooter,
            diagramsFolder: this.diagramsFolder,
            diagramPath,
            runId,
            project,
            projectFolder: this.projectFolder,
            releasesFolder: this.releasesFolder,
            rootAction,
            runInput: startRequest.runInput,
            startedAt: new Date().toISOString(),
        }, {
            actionWorktreeRunService: this.actionWorktreeRunService,
            agentExecutor: this.agentExecutor,
            agentRunnerService: this.agentRunnerService,
            commandRunner: this.commandRunner,
            commandWindowRunner: this.commandWindowRunner,
            diagramOutputWatcherFactory: this.diagramOutputWatcherFactory,
            localGitService: this.localGitService,
            publisher: this.publish.bind(this),
        });
        this.runEvents.set(runId, []);
        this.runs.set(runId, run);
        run.start(this.finalizeRun.bind(this, run));

        return runId;
    }

    async reserveConversation(request) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        if (startRequest.runInput.continueFrom) throw new Error('Continuing an agent conversation does not require a reservation');
        const action = await this.loadRootAction(startRequest.actionId);
        if (action.type !== 'agent') throw new Error('Cannot reserve a conversation for a command action');
        const origin = activityOrigin(startRequest.context);
        const conversationId = `agent-${crypto.randomUUID()}`;
        const reference = this.localGitService.activityConversationReference(this.projectFolder, origin, conversationId);
        const { activityPath } = parseConversationActivityReference(reference);
        const reservation = { activityPath, conversationId, reference };
        this.conversationReservations.set(reference, reservation);

        return reservation;
    }
